346	  override runUpdate(deltaTime: number): void {
347	    if (!this._built) return;
348	    const root = this.getTimelineRoot();
349	    if (!root?.visible) return;
350	    const camera = this._context?.camera as THREE.Camera | undefined;
351	    if (!camera) return;
352	
353	    const rootParent = root.parent;
354	    if (rootParent) {
355	      rootParent.getWorldQuaternion(this._parentWorldQ);
356	      root.quaternion.copy(this._parentWorldQ.invert());
357	    }
358	
359	    const { flameLen, throttle, elapsed } = this._sim.update(deltaTime);
360	    const flameLenScaled = flameLen * this._intensity;
361	    const throttleScaled = throttle * this._intensity;
362	    for (const eng of this._inner) {
363	      eng.group.scale.y = this._cfg.baseLength * flameLenScaled;
364	      eng.mat.uniforms.uTime.value = elapsed;
365	      eng.mat.uniforms.uFlameLen.value = flameLenScaled;
366	      eng.mat.uniforms.uThrottle.value = throttleScaled;
367	      for (const b of eng.blooms) {
368	        b.mesh.quaternion.copy(camera.quaternion);
369	        b.mat.uniforms.uTime.value = elapsed;
370	        b.mat.uniforms.uIntensity.value =
371	          b.baseIntensity *
372	          this._cfg.innerBloom *
373	          throttleScaled *
374	          (0.8 + flameLenScaled * 0.5);
375	        b.mesh.position.y = b.yOffset;
376	      }
377	    }
378	
379	    const parent = this._parent;
380	    if (!parent) return;
381	    parent.group.scale.y = this._cfg.parentLength * flameLenScaled;
382	    parent.mat.uniforms.uTime.value = elapsed;
383	    parent.mat.uniforms.uFlameLen.value = flameLenScaled;
384	    parent.mat.uniforms.uThrottle.value = throttleScaled;
385	    for (const b of parent.blooms) {
386	      b.mesh.quaternion.copy(camera.quaternion);
387	      b.mat.uniforms.uTime.value = elapsed;
388	      b.mat.uniforms.uIntensity.value =
389	        b.baseIntensity *
390	        this._cfg.parentBloom *
391	        throttleScaled *
392	        (0.7 + flameLenScaled * 0.5);
393	      b.mesh.position.y = b.yOffset;
394	    }
395	  }
