406	  private _build(): void {
407	    const root = this.getTimelineRoot();
408	    if (!root) return;
409	    const shaderOwnerId = this.getShaderOwnerId();
410	    this.releaseShaders(shaderOwnerId);
411	    this._teardown();
412	    const cfg = this._cfg;
413	    const nr = cfg.nozzleRadius;
414	    const gridStepX = nr * Math.max(0.2, cfg.nozzleGapX);
415	    const gridStepZ = nr * Math.max(0.2, cfg.nozzleGapZ);
416	    const tipY = -(cfg.baseLength * 0.85);
417	    const parentR = Math.max(gridStepX, gridStepZ) * 1.9 + nr;
418	    const innerVert = JetEngine.innerVertGLSL(cfg);
419	    const innerFrag = JetEngine.innerFragGLSL(cfg);
420	    const parentVert = JetEngine.parentVertGLSL(cfg);
421	    const parentFrag = JetEngine.parentFragGLSL(cfg);
422	
423	    const layout: ReadonlyArray<readonly [number, number]> = [
424	      [-1, 2],
425	      [0, 2],
426	      [1, 2],
427	      [-0.5, 1],
428	      [0.5, 1],
429	      [-1, 0],
430	      [0, 0],
431	      [1, 0],
432	      [-0.5, -1],
433	      [0.5, -1],
434	      [-1, -2],
435	      [0, -2],
436	      [1, -2],
437	    ];
438	
439	    layout.forEach(([gx, gz], i) => {
440	      const pos = new THREE.Vector3(gx * gridStepX, 0, gz * gridStepZ);
441	      const isCenter = gx === 0 && gz === 0;
442	      if (!this._innerGeo) {
443	        this._innerGeo = new THREE.CylinderGeometry(0.004, nr, 1.0, 24, 20, true);
444	      }
445	      const geo = this._innerGeo;
446	      const mat = new THREE.ShaderMaterial({
447	        uniforms: {
448	          uTime: { value: 0 },
449	          uFlameLen: { value: 1 },
450	          uThrottle: { value: 1 },
451	          uSeed: { value: i * 2.71828 + 0.5 },
452	        },
453	        vertexShader: innerVert,
454	        fragmentShader: innerFrag,
455	        transparent: true,
456	        side: THREE.DoubleSide,
457	        depthWrite: false,
458	        blending: THREE.AdditiveBlending,
459	      });
460	      this.registerShader({
461	        key: this.createShaderKey(`inner.${i}`),
462	        ownerId: shaderOwnerId,
463	        material: mat,
464	        autoResolution: false,
465	      });
466	      const mesh = new THREE.Mesh(geo, mat);
467	      mesh.rotation.x = Math.PI;
468	      mesh.position.y = -0.5;
469	      mesh.layers.set(THREE_LAYER_ROCKET);
470	      mesh.renderOrder = JetEngine.MESH_RENDER_ORDER;
471	      const group = new THREE.Group();
472	      group.add(mesh);
473	      group.position.copy(pos);
474	      if (!isCenter) {
475	        const dir = new THREE.Vector3(0, tipY, 0).sub(pos).normalize();
476	        group.quaternion.setFromUnitVectors(new THREE.Vector3(0, -1, 0), dir);
477	      }
478	      root.add(group);
479	      const blooms = this._buildBlooms(group, [
480	        {
481	          color: [0.3, 0.6, 1.0],
482	          radius: 6.0,
483	          size: nr * 5,
484	          baseI: 0.55,
485	          y: -0.05,
486	        },
487	        {
488	          color: [0.15, 0.4, 1.0],
489	          radius: 2.5,
490	          size: nr * 10,
491	          baseI: 0.35,
492	          y: -0.35,
493	        },
494	      ]);
495	      if (isCenter) {
496	        blooms.push(
497	          ...this._buildBlooms(group, [
498	            {
499	              color: cfg.innerColor.top,
500	              radius: 6.8,
501	              size: nr * 10.5,
502	              baseI: 0.42,
503	              y: 0.04,
504	            },
505	          ]),
506	        );
507	      }
508	      this._inner.push({ group, mat, blooms });
509	    });
510	
511	    const pGeo = new THREE.CylinderGeometry(0.01, parentR, 1.0, 40, 28, true);
512	    const pMat = new THREE.ShaderMaterial({
513	      uniforms: {
514	        uTime: { value: 0 },
515	        uFlameLen: { value: 1 },
516	        uThrottle: { value: 1 },
517	        uSeed: { value: 99.9 },
518	      },
519	      vertexShader: parentVert,
520	      fragmentShader: parentFrag,
521	      transparent: true,
522	      side: THREE.DoubleSide,
523	      depthWrite: false,
524	      blending: THREE.AdditiveBlending,
525	    });
526	    this.registerShader({
527	      key: this.createShaderKey("parent"),
528	      ownerId: shaderOwnerId,
529	      material: pMat,
530	      autoResolution: false,
531	    });
532	    const pMesh = new THREE.Mesh(pGeo, pMat);
533	    pMesh.rotation.x = Math.PI;
534	    pMesh.position.y = -0.5;
535	    pMesh.layers.set(THREE_LAYER_ROCKET);
536	    pMesh.renderOrder = JetEngine.MESH_RENDER_ORDER;
537	    const pGroup = new THREE.Group();
538	    pGroup.add(pMesh);
539	    root.add(pGroup);
540	    const pBlooms = this._buildBlooms(pGroup, [
541	      {
542	        color: [1.0, 0.95, 0.85],
543	        radius: 5.0,
544	        size: parentR * 4.5,
545	        baseI: 0.22,
546	        y: -0.05,
547	      },
548	      {
549	        color: [0.9, 0.95, 1.0],
550	        radius: 2.0,
551	        size: parentR * 7.0,
552	        baseI: 0.14,
553	        y: -0.4,
554	      },
555	    ]);
556	    this._parent = { group: pGroup, mat: pMat, blooms: pBlooms };
557	  }
558	
559	  private _teardown(): void {
560	    this._innerGeo?.dispose();
561	    this._innerGeo = null;
562	    for (const eng of this._inner) {
563	      eng.group.traverse((obj) => {
564	        if (obj instanceof THREE.Mesh) {
565	          (obj.material as THREE.Material).dispose();
566	        }
